/**
 * Build a diagnostic Error from a failed `Response`.
 *
 * Replaces the old "label: <statusText>" error pattern: `statusText` is
 * empty over HTTP/2 (the prod transport), so it carried no information. This
 * helper surfaces the status code plus the server's error body — the server
 * returns `{ error }` JSON on 4xx/5xx (see `response-helpers.ts`). Fail loud,
 * with something readable in the log. See design log #203.
 *
 * Pure (no DOM/`window`), so it is importable from the service worker too.
 * It never throws: an unreadable body degrades to just the label + status, so
 * minimal `fetch` stubs in tests stay legible rather than masking the real
 * error with a TypeError from the error-builder itself.
 */
export async function apiError(response: Response, label: string): Promise<Error> {
    const detail = await readBodyDetail(response);
    const status = typeof response.status === 'number' ? String(response.status) : '';
    return new Error([`${label}:`, status, detail].filter(Boolean).join(' '));
}

async function readBodyDetail(response: Response): Promise<string> {
    let text: string;
    try {
        text = await response.text();
    } catch {
        return '';
    }
    if (!text) return '';
    try {
        const body: unknown = JSON.parse(text);
        if (body !== null && typeof body === 'object' && typeof (body as { error?: unknown }).error === 'string') {
            return (body as { error: string }).error;
        }
    } catch {
        // Not JSON — fall through to the raw text.
    }
    return text;
}

/**
 * A JSON client bound to one API root — the shape every section service repeats.
 *
 * `get` throws when the server says the thing is missing; `find` answers null on
 * a 404 instead. That is the same distinction the repositories already draw
 * between `getById` (throws `NotFoundError`) and `findById` (returns null), so a
 * nullable read keeps its name from SQL through to the screen. A route that
 * serves `null` in a 200 body rather than a 404 is still a `find*` on the
 * service — the name describes the contract, not the transport — and reaches for
 * `get<T | null>` here.
 *
 * Errors carry the request line instead of a hand-written label. The method and
 * path are always accurate, where prose drifts as routes are renamed (story 116
 * renamed `/nutrition*` and `/food-library*` out from under theirs); `apiError`
 * appends the status and the server's `{ error }` body.
 *
 * A route needing its own abort signal, a tolerated non-2xx, or its own
 * error-body parsing calls `fetch` directly and says so at the call site —
 * five of them do, and forcing options into this client for their sake would
 * cost every other caller.
 */
export function createJsonClient(root: string) {
    async function send(
        method: string,
        path: string,
        body?: unknown,
        allow: readonly number[] = [],
    ): Promise<Response> {
        const response = await fetch(`${root}${path}`, {
            method,
            ...(body === undefined ? null : {
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body),
            }),
        });
        if (!response.ok && !allow.includes(response.status)) {
            throw await apiError(response, `${method} ${path}`);
        }
        return response;
    }

    return {
        /** GET, parsed as JSON. Throws on every non-2xx, a 404 included. */
        async get<T>(path: string): Promise<T> {
            return (await send('GET', path)).json();
        },
        /** GET where absence is an answer: null on 404, throws on anything else. */
        async find<T>(path: string): Promise<T | null> {
            const response = await send('GET', path, undefined, [404]);
            return response.status === 404 ? null : response.json();
        },
        async post<T>(path: string, body?: unknown): Promise<T> {
            return (await send('POST', path, body)).json();
        },
        /** POST whose response carries no body to read. */
        async postVoid(path: string, body?: unknown): Promise<void> {
            await send('POST', path, body);
        },
        async patch<T>(path: string, body?: unknown): Promise<T> {
            return (await send('PATCH', path, body)).json();
        },
        async put<T>(path: string, body?: unknown): Promise<T> {
            return (await send('PUT', path, body)).json();
        },
        async del(path: string): Promise<void> {
            await send('DELETE', path);
        },
    };
}
